// Native golden cases: gml_Script_spawnCuratedWaves at source wave 110.
// Values are captured native spawnEnemies arguments, not generated by this port.
#include "source_waves.h"
#include "game.h"
#include <cassert>
#include <cstring>
#include <cstdio>
#include <initializer_list>
using namespace nova;
int main(){
 static_assert(sizeof(SourceSpawnSpec)==31*sizeof(int32_t),"native argument order");
 assert(SOURCE_ENEMY_COUNT==43);
 // Golden execution of setWaveDelay for all 864 original OBJT identifiers.
 // These representative extremes catch the old 450-2*wave substitute and
 // accidental conversion of original 60 Hz frames inside this source table.
 assert(sourceEnemyDelayFrames(SE_ASTEROID)==0);
 assert(sourceEnemyDelayFrames(SE_INTERCEPTOR)==60);
 assert(sourceEnemyDelayFrames(SE_WARDEN)==150);
 assert(sourceEnemyDelayFrames(SE_BULWARK)==18000);
 assert(sourceEnemyDelayFrames(SE_JUGGERNAUT)==5200);
 assert(sourceEnemyDelayFrames(SE_CERATOTITAN)==15000);
 assert(sourceEnemyDelayFrames(SE_NULL)==6400);
 assert(sourceEnemyDelayFrames((SourceEnemy)SOURCE_UNDEFINED)==0);
 assert(sourceEnemyInfo(SE_MYRMIDON,0).min_wave==45);
 assert(sourceEnemyInfo(SE_MYRMIDON,RUN_ELITE).min_wave==20);
 assert(sourceEnemyInfo(SE_MYRMIDON,RUN_ANNIHILATION).min_wave==40);
 assert(sourceEnemyInfo(SE_MYRMIDON,RUN_ELITE|RUN_ANNIHILATION).min_wave==15);
 assert(sourceEnemyInfo(SE_HOST,RUN_ANNIHILATION).champion_wave==10);
 assert(sourceEnemyInfo(SE_SCION,RUN_ANNIHILATION).min_wave==90);
 SourceSpawnSpec out[SOURCE_MAX_SPECS];uint32_t rng=17;
 assert(sourceCuratedPattern(2,110,0,rng,out,8)==1);
 assert(out[0].enemy==SE_HOST&&out[0].count==1&&out[0].rarity==2&&out[0].behavior==4);
 assert(out[0].follower==SE_HOST&&out[0].follower_count==4&&out[0].action_delay_ticks==45);
 assert(out[0].repeat_formation==3&&out[0].repeat_size_q8==224&&out[0].entry==SOURCE_UNDEFINED);
 assert(sourceCuratedPattern(5,110,0,rng,out,8)==2);
 assert(out[0].enemy==SE_ASTEROID&&out[0].count==7&&out[1].enemy==SE_ASTEROID_MEGA&&out[1].count==2);
 assert(sourceCuratedPattern(12,110,0,rng,out,8)==3);
 for(unsigned i=0;i<3;i++){assert(out[i].enemy==SE_BEAMCASTER&&out[i].rarity==2&&out[i].follower_count==4);
  assert(out[i].behavior_parameter1_q8==(i==1?768:-768)&&out[i].behavior_parameter2_q8==8192);
  assert(out[i].added_delay_ticks==int(i*80)&&out[i].follower_max_rarity==1);}
 assert(sourceCuratedPattern(14,110,0,rng,out,8)==2);
 assert(out[0].enemy==SE_TRACER&&out[0].count==2&&out[0].spawn==5&&out[0].spawn_parameter_q8==10240);
 assert(out[0].added_delay_ticks==480&&out[0].behavior_parameter2_q8==8320);
 assert(out[1].follower==SE_HAMMERHEAD&&out[1].follower_count==4&&out[1].break_delay_ticks==2);
 assert(sourceCuratedPattern(20,110,0,rng,out,8)==1);
 assert(out[0].enemy==SE_DWELLER_WARRIOR&&out[0].follower==SE_DWELLER_GUARD&&out[0].follower_count==2);
 assert(out[0].add_enemy==SE_DWELLER_DRONE&&out[0].add_frequency_ticks==90&&out[0].support_count==12);
 assert(out[0].repeat_formation==3&&out[0].repeat_size_q8==218);
 assert(!sourceCuratedWave(19,0,rng,out,8));
 assert(sourceCuratedWave(20,0,rng,out,8)); // caller owns boss precedence, including endless irregular bosses
 assert(!sourceCuratedWave(15,0,rng,out,8));
 assert(sourceCuratedWave(15,0,rng,out,8,true)); // native Cosmic Ballet interval: 5, not 10
 // Independently executed PC 1.2.38.4 x64 quantity arithmetic, from
 // spawnDynamicWaves 0x140630c30..0x140631f07. Q16 tolerance covers
 // rounding the original floating coefficients onto the calculator grid.
 struct QuantityCase {unsigned wave,flags,first,second,expected;};
 const QuantityCase quantities[]={
  {10,0,16384,49152,217421},{50,0,49152,16384,349460},
  {120,0,16384,49152,368640},{121,0,49152,16384,504269},
  {240,0,16384,49152,568382},{300,0,16384,49152,568382},
  {90,RUN_ELITE|RUN_ANNIHILATION,16384,49152,377508},
  {150,RUN_ELITE,49152,16384,552772}
 };
 for(const QuantityCase& q:quantities){
  unsigned actual=sourceDynamicAmountQ16(SE_INTERCEPTOR,q.wave,(uint16_t)q.flags,q.first,q.second,32768);
  int error=(int)actual-(int)q.expected;assert(error>=-96&&error<=96);
 }
 assert(sourceDynamicAmountQ16(SE_INTERCEPTOR,50,0,0,65535,32768)<
        sourceDynamicAmountQ16(SE_INTERCEPTOR,50,0,65535,0,32768));
 for(unsigned mode=0;mode<4;mode++)for(unsigned wave: {10u,30u,110u,240u,400u})for(unsigned pattern=0;pattern<22;pattern++){
  uint16_t flags=(mode&1?RUN_ELITE:0)|(mode&2?RUN_ANNIHILATION:0);
  for(unsigned seed=0;seed<64;seed++){rng=seed;unsigned count=sourceCuratedPattern(pattern,wave,flags,rng,out,8);assert(count>0&&count<=8);
   for(unsigned i=0;i<count;i++){assert(out[i].enemy>=0&&out[i].enemy<SOURCE_ENEMY_COUNT);assert(out[i].count==SOURCE_UNDEFINED||out[i].count>0);}}
 }
 struct {SourceSpawnSpec first;uint32_t guard[4];} bounded;
 for(unsigned i=0;i<4;i++)bounded.guard[i]=0xfeedbeefu;
 assert(sourceCuratedPattern(12,110,0,rng,&bounded.first,1)==1);
 for(unsigned i=0;i<4;i++)assert(bounded.guard[i]==0xfeedbeefu);
 assert(!sourceCuratedPattern(12,110,0,rng,nullptr,8));
 puts("Source waves: 22 recipes / 43 enemy families / four difficulty tables / native golden cases PASS");
}
